(()=>{'use strict';const normalize=s=>String(s??'').normalize('NFKC').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[\u064b-\u065f\u0670\u0640]/g,'').replace(/[\u200c\u200d]/g,'').replace(/\s+/g,' ').trim().toLocaleLowerCase('fa');window.SamandisTaskMatches=function(t,query){const terms=normalize(query).split(' ').filter(Boolean);if(!terms.length)return true;const shared=document.body.classList.contains('shared-app'),ids=[t.owner_id??t.owner,...(t.collaborators||[])],names=ids.map(id=>{if(shared&&typeof members!=='undefined')return members.find(m=>m.id===id)?.name||'';return typeof people!=='undefined'?people[id]||'':''});const text=normalize([t.title,t.description,t.status,t.priority,t.code,t.id,...names,...(t.responsible_names||[]),t.responsible_name].filter(Boolean).join(' '));return terms.every(term=>text.includes(term))};})();
